      if (item.status) item.status.textContent = '\u6B63\u5728\u4E0A\u4F20\u2026';
      let errorMessage = item.file.size > 10 * 1024 * 1024 ? '\u6587\u4EF6\u5927\u5C0F\u4E0D\u80FD\u8D85\u8FC7 10 MB' : '';
